/* @lc app=leetcode id=2518 lang=kotlin */ class Solution { fun countPartitions(nums: IntArray, k: Int) = 1000000007L.let { M -> if (nums.sumOf { it.toLong() } < 2 * k) 0 else LongArray(k).apply { this[0] = 1 }.also { dp -> nums.forEach { n -> (k - 1 downTo n).forEach { i -> dp[i] = (dp[i] + dp[i - n]) % M } } }.let { dp -> nums.fold(1L) { acc, _ -> (acc * 2) % M }.let { total -> (total - 2 * dp.sum() % M + M) % M }.toInt() } } }